<template><main class="operations" v-loading="loading"><header><div><h1>{{title}}</h1><p>{{description}}</p></div><el-button @click="load">刷新</el-button></header><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-tabs v-model="tab"><el-tab-pane v-if="showSection('personnel') && (can('workflow.manage')||can('staff.onboarding.view'))" label="员工入职" name="onboarding"><StaffOnboardingCenter :can-configure="can('workflow.manage')"/></el-tab-pane><el-tab-pane v-if="showSection('personnel') && (can('workflow.manage')||can('staff.offboarding.view'))" label="离职交接" name="offboarding"><StaffOffboardingCenter/></el-tab-pane><el-tab-pane v-if="showSection('personnel') && (can('staff.support.view'))" label="支援申请记录" name="support"><StaffSupportRecords :rows="supportRows"/></el-tab-pane><el-tab-pane v-if="showSection('personnel') && (can('staff.transfers.view'))" label="调店记录" name="transfers"><div class="filters"><el-input v-model="query.q" clearable placeholder="搜索员工、原店或接收店"/><el-select v-model="query.status" clearable placeholder="全部状态"><el-option v-for="(label,value) in transferLabels" :key="value" :label="label" :value="value"/></el-select><StoreRegionSelect v-model="query.store_id" :stores="config.stores" input-width="240px"/><el-date-picker v-model="query.from" type="date" value-format="YYYY-MM-DD" placeholder="开始日期"/><el-date-picker v-model="query.to" type="date" value-format="YYYY-MM-DD" placeholder="结束日期"/><el-button @click="loadTransfers">查询</el-button><el-button @click="exportTransfers">导出记录</el-button></div><el-table :data="transfers"><el-table-column prop="employee_name" label="员工" width="130"/><el-table-column prop="from_store_name" label="原门店" min-width="170"/><el-table-column prop="to_store_name" label="接收门店" min-width="170"/><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.status==='accepted'?'success':row.status==='pending'?'warning':'info'">{{transferLabels[row.status]}}</el-tag></template></el-table-column><el-table-column label="发起"><template #default="{row}">{{row.initiated_name}}<p>{{time(row.created_at)}}</p></template></el-table-column><el-table-column label="签收／处理"><template #default="{row}">{{row.decided_name||'—'}}<p>{{time(row.decided_at)}}</p></template></el-table-column><el-table-column prop="received_position_name" label="接收后小程序岗位" min-width="150"/><el-table-column prop="reason" label="调店原因" min-width="180"/><el-table-column prop="decision_note" label="处理意见" min-width="180"/></el-table><el-empty v-if="!transfers.length" description="暂无调店记录；由店长在小程序发起"/></el-tab-pane><el-tab-pane v-if="showSection('announcements') && (can('store-notices.manage'))" label="公告通知" name="announcements"><div class="toolbar"><span>阅读与确认分别记录，已发布正文保留。</span><el-button type="primary" @click="edit()">发布通知</el-button></div><el-table :data="announcements"><el-table-column prop="title" label="标题" min-width="220"/><el-table-column label="阅读范围" min-width="180"><template #default="{row}">{{row.mode==='all'?'全部门店':row.mode==='regions'?'指定区域':'指定门店'}} · {{row.audience_mode==='all'?'全部门店人员':roleNames(row)}}</template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}">{{states[row.status]}}</template></el-table-column><el-table-column label="确认要求" width="110"><template #default="{row}">{{row.requires_confirm?'需确认知悉':'阅读即可'}}</template></el-table-column><el-table-column label="发布时间"><template #default="{row}">{{time(row.published_at)}}</template></el-table-column><el-table-column label="操作" width="210"><template #default="{row}"><el-button v-if="row.status==='draft'" link type="primary" @click="edit(row)">编辑</el-button><el-button v-if="row.status!=='draft'" link @click="report(row)">阅读回执</el-button><el-button v-if="row.status==='published'" link type="danger" @click="hide(row)">撤回</el-button></template></el-table-column></el-table></el-tab-pane><el-tab-pane v-if="showSection('announcements') && (can('store-notices.manage'))" label="自动提醒" name="rules"><div class="rules"><div v-for="(label,key) in config.types" :key="key"><span>{{label}}</span><el-switch v-model="config.rules[key]"/></div><el-button type="primary" @click="saveRules">保存提醒设置</el-button><p>关闭后停止生成新的提醒，已送达消息保留。微信订阅推送尚未接入。</p></div></el-tab-pane></el-tabs><el-dialog v-model="editorOpen" title="公告通知" width="720px"><el-form label-position="top"><el-form-item label="标题"><el-input v-model="form.title" maxlength="120"/></el-form-item><el-form-item label="正文"><el-input v-model="form.content" type="textarea" :rows="7" maxlength="8000"/></el-form-item><el-form-item label="适用门店"><el-radio-group v-model="form.mode"><el-radio-button value="all">全部门店</el-radio-button><el-radio-button value="stores">指定门店</el-radio-button><el-radio-button value="regions">指定区域</el-radio-button></el-radio-group><StoreRegionSelect v-if="form.mode==='stores'" v-model="form.store_ids" multiple :stores="config.stores" input-width="100%"/><el-select v-if="form.mode==='regions'" v-model="form.region_ids" multiple filterable style="width:100%"><el-option v-for="r in config.regions" :key="r.id" :value="r.id" :label="r.name"/></el-select></el-form-item><el-form-item label="阅读对象"><el-radio-group v-model="form.audience_mode"><el-radio-button value="all">全部门店人员</el-radio-button><el-radio-button value="positions">指定岗位</el-radio-button></el-radio-group><el-select v-if="form.audience_mode==='positions'" v-model="form.position_ids" multiple filterable style="width:100%"><el-option v-for="p in config.positions" :key="p.id" :value="p.id" :label="p.name"/></el-select></el-form-item><el-checkbox v-model="form.requires_confirm">要求接收人确认知悉</el-checkbox></el-form><template #footer><el-button @click="editorOpen=false">取消</el-button><el-button :disabled="busy" @click="save('draft')">保存草稿</el-button><el-button :disabled="busy" type="primary" @click="save('published')">发布通知</el-button></template></el-dialog><el-drawer v-model="reportOpen" title="公告阅读回执" size="800px"><div class="counts"><span>未读 {{reportRows.filter(r=>r.status==='未读').length}}</span><span>已读 {{reportRows.filter(r=>r.status==='已读').length}}</span><span>已确认 {{reportRows.filter(r=>r.status==='已确认').length}}</span></div><el-table :data="reportRows"><el-table-column prop="name" label="人员"/><el-table-column label="岗位"><template #default="{row}">{{row.positions?.join('、')}}</template></el-table-column><el-table-column prop="status" label="状态"/><el-table-column label="阅读时间"><template #default="{row}">{{time(row.read_at)}}</template></el-table-column><el-table-column label="确认时间"><template #default="{row}">{{time(row.confirmed_at)}}</template></el-table-column></el-table></el-drawer></main></template>
<script setup>
import {ref,computed,onMounted} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {storeOperationsApi as api} from '@/api'
import StoreRegionSelect from '@/components/StoreRegionSelect.vue'
import StaffSupportRecords from '@/components/StaffSupportRecords.vue'
import StaffOffboardingCenter from '@/components/StaffOffboardingCenter.vue'
import StaffOnboardingCenter from '@/components/StaffOnboardingCenter.vue'
const props=defineProps({section:{type:String,default:''}})
const showSection=section=>!props.section||props.section===section
const title=computed(()=>props.section==='personnel'?'人员流程':props.section==='announcements'?'公告与提醒':'门店流程与通知')
const description=computed(()=>props.section==='personnel'?'查询入职、离职交接、支援和调店过程。':props.section==='announcements'?'发布门店公告、查看阅读回执及设置自动提醒。':'调店在手机发起和签收；后台查询过程、发布公告及查看回执。')
const config=ref({permissions:[],stores:[],positions:[],regions:[],rules:{},types:{}}),transfers=ref([]),supportRows=ref([]),announcements=ref([]),loading=ref(false),busy=ref(false),error=ref(''),tab=ref('transfers'),query=ref({q:'',status:'',store_id:null,from:'',to:''}),form=ref({}),editorOpen=ref(false),reportOpen=ref(false),reportRows=ref([])
const transferLabels={pending:'待接收',accepted:'已接收',rejected:'已拒绝',cancelled:'已撤回'},states={draft:'草稿',published:'已发布',hidden:'已撤回'},can=p=>config.value.permissions.some(v=>v==='*'||v===p),time=v=>v?new Date(v).toLocaleString('zh-CN',{hour12:false}):'—',roleNames=r=>(r.position_ids||[]).map(id=>config.value.positions.find(p=>p.id===id)?.name).filter(Boolean).join('、')
async function attempt(fn){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function loadTransfers(){transfers.value=(await api.transfers(query.value)).rows}
async function load(){loading.value=true;try{config.value=await api.config();if(showSection('personnel')){tab.value=can('staff.transfers.view')?'transfers':can('workflow.manage')||can('staff.onboarding.view')?'onboarding':can('staff.support.view')?'support':'offboarding';if(can('staff.transfers.view'))await loadTransfers();if(can('staff.support.view'))supportRows.value=(await api.supportRequests()).rows}else tab.value='announcements';if(showSection('announcements')&&!['staff.transfers.view','staff.support.view','staff.onboarding.view','staff.offboarding.view','workflow.manage'].some(can))tab.value='announcements';if(showSection('announcements')&&can('store-notices.manage'))announcements.value=(await api.announcements()).rows;error.value=''}catch(e){error.value=e.message}finally{loading.value=false}}
function edit(row){form.value=row?{...row,requires_confirm:!!row.requires_confirm}:{title:'',content:'',mode:'all',store_ids:[],region_ids:[],audience_mode:'all',position_ids:[],requires_confirm:false};editorOpen.value=true}
const save=status=>attempt(async()=>{await api.saveAnnouncement({...form.value,status});editorOpen.value=false;await load();ElMessage.success(status==='published'?'已发布通知':'已保存草稿')})
async function hide(row){try{await ElMessageBox.confirm('撤回后不再向员工展示，阅读与确认记录保留。','撤回通知');await attempt(async()=>{await api.saveAnnouncement({...row,status:'hidden'});await load()})}catch{}}
const report=row=>attempt(async()=>{reportRows.value=(await api.report(row.id)).rows;reportOpen.value=true})
const saveRules=()=>attempt(async()=>{await api.saveRules(config.value.rules);ElMessage.success('提醒设置已保存')})
const exportTransfers=()=>attempt(async()=>{const blob=await api.exportTransfers(query.value),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='员工调店记录.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)})
onMounted(load)
</script>
<style scoped>.operations{padding:24px;max-width:1500px;margin:auto}.operations header{display:flex;justify-content:space-between;align-items:center;margin-bottom:24px}.eyebrow{font-size:12px;color:#8b98a5}h1{font-size:20px;margin:0 0 8px}p{font-size:12px;color:#8795a3;line-height:1.7}.filters{display:flex;flex-wrap:wrap;gap:12px;align-items:center;margin:16px 0}.filters>.el-input{max-width:280px}.filters>.el-select{max-width:150px}.toolbar{display:flex;justify-content:space-between;align-items:center;padding:16px 0}.toolbar span{font-size:13px;color:#8b98a5}.rules{max-width:500px;padding:20px 0}.rules>div{display:flex;justify-content:space-between;align-items:center;padding:14px 0;border-bottom:1px solid #edf0f2}.rules>.el-button{margin-top:24px}.counts{display:flex;gap:28px;margin-bottom:24px;font-size:14px}</style>
